package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct { // 01 AMT-REC, 11 bytes
	ArAcct string // PIC X(4) @0 len=4
	ArAmt decimal.Decimal // PIC 9(5)V99 @4 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(7)V99 len=9 = 0
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99 len=7 = 0
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99 len=7 = 0
var WsOverflows int64 = 0 // PIC 99 len=2 = 0
var WsCount int64 = 0 // PIC 99 len=2 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V9 len=6 = 0
var WsAmtEd string // PIC ZZ,ZZ9.99 len=9
var WsWrapEd string // PIC ZZ,ZZ9.99 len=9
var WsSafeEd string // PIC ZZ,ZZ9.99 len=9
var WsHalfEd string // PIC ZZ,ZZ9.9 len=8

var AmtRecInst AmtRec

var amtLines []string
var amtIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func pow10(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func storeScaled(v decimal.Decimal, scale int, totalDigits int) decimal.Decimal {
	t := v.Truncate(int32(scale))
	shifted := t.Shift(int32(scale)).IntPart()
	mod := pow10(totalDigits)
	wrapped := shifted % mod
	return decimal.New(wrapped, int32(-scale))
}

func formatEdited(v decimal.Decimal, intDigits int, decDigits int) string {
	t := v.Truncate(int32(decDigits))
	abs := t.Abs()
	scaled := abs.Shift(int32(decDigits)).IntPart()
	powDec := pow10(decDigits)
	intPart := scaled / powDec
	fracPart := scaled % powDec
	if fracPart < 0 {
		fracPart = -fracPart
	}
	modInt := pow10(intDigits)
	intMod := intPart % modInt
	intStr := fmt.Sprintf("%0*d", intDigits, intMod)
	fracStr := fmt.Sprintf("%0*d", decDigits, fracPart)
	var intEd string
	if intDigits == 5 {
		digits := []byte(intStr)
		out := make([]byte, 6)
		suppressed := true
		// first two Z's
		for i := 0; i < 2; i++ {
			d := digits[i]
			if suppressed && d == '0' {
				out[i] = ' '
			} else {
				out[i] = d
				if suppressed && d != '0' {
					suppressed = false
				} else if !suppressed {
					// stay unsuppressed
				} else {
					// suppressed and d=='0' handled above
				}
				if !suppressed {
					// keep false
				} else {
					// was suppressed and d != '0'
					suppressed = false
				}
				// Actually ensure: if we printed because !suppressed, stay false
				// The above logic already sets false when needed.
				// Fix: if previously unsuppressed, suppressed is false already.
				// Recompute correctly:
			}
		}
		// Recompute suppression correctly for comma decision:
		// suppressed is true only if digits[0]=='0' and digits[1]=='0'
		// Our loop above may have mangled; recompute simply:
		suppressed = (digits[0] == '0' && digits[1] == '0' && out[0] == ' ' && out[1] == ' ')
		// But if digits[0]=='0' and digits[1]!='0', suppressed should be false.
		// The simple check: suppressed = (out[0]==' ' && out[1]==' ')
		// Actually if first non-zero appears in first two, out will have digit.
		suppressed = (out[0] == ' ' && out[1] == ' ')
		if suppressed {
			out[2] = ' '
		} else {
			out[2] = ','
		}
		// next two Z's: digits[2], digits[3]
		for j := 0; j < 2; j++ {
			d := digits[2+j]
			pos := 3 + j
			if suppressed && d == '0' {
				// check if all remaining integer digits including last are zero?
				// Z still spaces even if later non-zero; so space now.
				// But need to look ahead: if later digits contain non-zero, still space (leading).
				out[pos] = ' '
			} else {
				out[pos] = d
				suppressed = false
			}
		}
		out[5] = digits[4]
		intEd = string(out)
		_ = strings.Contains // avoid unused
	} else {
		intEd = intStr
	}
	return intEd + "." + fracStr
}

func parseAmtRec(line string) AmtRec {
	padded := line
	if len(padded) < 11 {
		padded = padded + strings.Repeat(" ", 11-len(padded))
	} else if len(padded) > 11 {
		padded = padded[:11]
	}
	acct := padded[0:4]
	amtStr := padded[4:11]
	var cents int64 = 0
	for i := 0; i < len(amtStr); i++ {
		c := amtStr[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else if c == ' ' {
			d = 0
		} else {
			d = 0
		}
		cents = cents*10 + d
	}
	return AmtRec{ArAcct: acct, ArAmt: decimal.New(cents, -2)}
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	sc := bufio.NewScanner(f)
	// Allow long lines; default is fine for 11 bytes, but enlarge buffer
	sc.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
	amtLines = nil
	amtIdx = 0
	for sc.Scan() {
		amtLines = append(amtLines, sc.Text())
	}
	if err := sc.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		f.Close()
		os.Exit(1)
	}
	f.Close()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if amtIdx >= len(amtLines) {
		WsEofFlag = "Y"
		return
	}
	line := amtLines[amtIdx]
	amtIdx++
	AmtRecInst = parseAmtRec(line)
}

func ProcessPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	sumBig := WsBigTotal.Add(AmtRecInst.ArAmt)
	WsBigTotal = storeScaled(sumBig, 2, 9)
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = storeScaled(WsBigTotal, 2, 7)
	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
	sumSafe := WsSafeTotal.Add(AmtRecInst.ArAmt)
	maxSafe := decimal.New(pow10(7)-1, -2)
	if sumSafe.GreaterThan(maxSafe) || sumSafe.Sign() < 0 {
		OverflowPara()
	} else {
		WsSafeTotal = sumSafe
	}
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 100
	// COMPUTE WS-HALF = AR-AMT / 2 (truncated)
	tmp := AmtRecInst.ArAmt.Mul(decimal.NewFromInt(5)).Shift(-1)
	tr := tmp.Truncate(1)
	WsHalf = storeScaled(tr, 1, 6)
	// MOVEs to edited
	WsAmtEd = formatEdited(AmtRecInst.ArAmt, 5, 2)
	WsWrapEd = formatEdited(WsWrapTotal, 5, 2)
	WsSafeEd = formatEdited(WsSafeTotal, 5, 2)
	WsHalfEd = formatEdited(WsHalf, 5, 1)
	fmt.Printf("%s %s %s %s %s\n", AmtRecInst.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("RECORDS: %02d\n", WsCount)
	fmt.Printf("OVERFLOWS: %02d\n", WsOverflows)
}

func OverflowPara() {
	WsOverflows = (WsOverflows + 1) % 100
}

func main() {
	MainPara()
}
